BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Auditor procedures when RSI is presented but methods cannot be confirmed
(1, 'Other Information and Supplementary Information', 'Oakmont Regional Transit Authority presents pension trend data as RSI alongside its audited financial statements. During inquiries, the finance director cannot explain the actuarial methods used to prepare the pension schedules. Under AU-C 730, what action should the auditor take?', '["Issue a qualified opinion on the basic financial statements due to the RSI uncertainty", "Include a statement in the RSI section that the results of limited procedures were inconclusive", "Report that the RSI was not audited and no opinion is expressed, with no additional modification", "Omit any reference to the pension trend data from the auditor''s report"]'::jsonb, 1, 'Correct (B): AU-C 730.09 requires that when the auditor is unable to complete the limited procedures on RSI, the auditor should include a statement in the RSI section of the report indicating that the results of limited procedures were inconclusive or that specific procedures could not be completed. Wrong (A): Although RSI issues may raise questions, they do not affect the opinion on the basic financial statements. Wrong (C): Simply reporting no opinion without noting the inability to complete procedures would omit required information. Wrong (D): The auditor cannot omit reference to RSI that is presented; the report must address it.', 'medium', 2),

-- Q2: hard / L4 — Evaluating whether other information requires financial statement revision
(1, 'Other Information and Supplementary Information', 'Alderman Technologies'' annual report states that total research and development expenditures were $12.3 million during the year. The audited financial statements report R&D expense of $8.7 million. The auditor, Vance & Caldwell LLP, investigates and determines that $3.6 million in capitalized development costs were properly classified under GAAP but were included as expenditures in the narrative. Evaluate the appropriate course of action.', '["Require management to restate the financial statements to include the $3.6 million as R&D expense", "Conclude that no material inconsistency exists because the difference results from a valid classification distinction rather than an error", "Issue an adverse opinion on the financial statements because the narrative contradicts the audited amounts", "Withdraw from the engagement due to irreconcilable differences between the financial statements and other information"]'::jsonb, 1, 'Correct (B): AU-C 720.12-.13 requires the auditor to assess whether a material inconsistency exists. When the difference between other information and the financial statements results from a legitimate classification distinction (expenditures vs. capitalized costs), the auditor may conclude no material inconsistency exists, although the auditor should consider whether the narrative is misleading. Wrong (A): The financial statements are correctly prepared under GAAP; restating them would be inappropriate. Wrong (C): An adverse opinion addresses financial statement misstatements, not classification differences in other information. Wrong (D): Withdrawal is a disproportionate response when the financial statements are fairly presented.', 'hard', 4),

-- Q3: medium / L2 — Auditor reporting on voluntarily presented supplementary info without engagement
(1, 'Other Information and Supplementary Information', 'Foxglove Consulting Group voluntarily includes a detailed schedule of employee compensation by department alongside its audited financial statements. The auditor, Merritt & Park CPA, was not engaged to report on this schedule. Under AU-C 725, what should the auditor do regarding the compensation schedule?', '["Issue an in-relation-to opinion on the schedule as part of the standard audit procedures", "Include an other-matter paragraph in the auditor''s report stating that the schedule was not audited and no opinion is expressed", "Perform substantive procedures on the compensation schedule before issuing the report", "Request that management remove the schedule from the document containing the financial statements"]'::jsonb, 1, 'Correct (B): AU-C 725.13-.14 states that when supplementary information accompanies the audited financial statements but the auditor has not been engaged to report on it, the auditor should include an other-matter paragraph disclaiming an opinion on the supplementary information. This clarifies the scope of the audit. Wrong (A): An in-relation-to opinion requires a specific engagement; the auditor was not engaged to report on this schedule. Wrong (C): While the auditor reads the information, substantive procedures are not required when the auditor is not engaged to report on supplementary information. Wrong (D): The auditor cannot require management to remove voluntarily presented information.', 'medium', 2),

-- Q4: hard / L4 — Multiple inconsistencies in other information with mixed resolution
(1, 'Other Information and Supplementary Information', 'During review of Sunbridge Holdings'' annual report, the auditor at Phelps & Granville CPA identifies three material inconsistencies between the other information and the audited financial statements. Management corrects two inconsistencies but refuses to revise the third, which overstates revenue growth by $2.1 million. The financial statements are fairly presented. Evaluate the auditor''s reporting obligation.', '["Issue a qualified opinion on the financial statements because management refused to correct one inconsistency", "Include a description of the remaining unresolved material inconsistency in the auditor''s report while issuing an unmodified opinion on the financial statements", "Withdraw from the engagement because management demonstrated a pattern of misrepresentation", "Accept the remaining inconsistency because two of three were corrected, demonstrating good faith"]'::jsonb, 1, 'Correct (B): AU-C 720.18-.19 requires the auditor to describe an unresolved material inconsistency in the auditor''s report. Because the financial statements are fairly presented, the opinion on them remains unmodified. The auditor''s report addresses the other information inconsistency separately from the financial statement opinion. Wrong (A): Although the inconsistency is concerning, a qualified opinion is appropriate only when the financial statements themselves are misstated, not when other information conflicts with correct financial statements. Wrong (C): Withdrawal is reserved for pervasive integrity concerns; correcting two of three inconsistencies does not establish a pattern warranting withdrawal. Wrong (D): The auditor cannot ignore an unresolved material inconsistency regardless of whether other inconsistencies were corrected.', 'hard', 4),

-- Q5: easy / L1 — Definition of other information vs. basic financial statements
(1, 'Other Information and Supplementary Information', 'Under AU-C 720, which of the following best describes what constitutes other information in a document containing audited financial statements?', '["The auditor''s report and any attached engagement letters", "Financial and nonfinancial information other than the financial statements and the auditor''s report thereon", "Only quantitative data tables that appear outside the financial statement footnotes", "Supplementary schedules specifically required by a financial reporting standard-setter"]'::jsonb, 1, 'Correct (B): AU-C 720.04 defines other information as financial and nonfinancial information, other than the financial statements and the auditor''s report thereon, included in a document containing audited financial statements. This includes items such as management letters, highlights, and operational summaries. Wrong (A): While the auditor''s report is in the same document, it is not classified as other information. Wrong (C): Other information includes both quantitative and narrative content, not only data tables. Wrong (D): Information required by a standard-setter is RSI under AU-C 730, which is distinct from other information under AU-C 720.', 'easy', 1),

-- Q6: easy / L1 — RSI limited procedures include inquiries
(1, 'Other Information and Supplementary Information', 'Which type of procedure does AU-C 730 require the auditor to perform on required supplementary information?', '["Detailed substantive tests of the RSI balances", "Inquiries of management about the methods of preparing the RSI", "A full-scope audit identical to the financial statement audit", "Confirmation of RSI amounts with independent third parties"]'::jsonb, 1, 'Correct (B): AU-C 730.07 requires the auditor to perform limited procedures on RSI, including making inquiries of management about the methods of preparing the information and whether it has been presented in accordance with prescribed guidelines. Wrong (A): Although substantive tests are used for financial statement assertions, RSI requires only limited procedures rather than detailed testing. Wrong (C): RSI is not subject to a full-scope audit; the auditor applies only limited procedures. Wrong (D): Confirmations with third parties are an audit procedure, not a limited procedure applied to RSI.', 'easy', 1),

-- Q7: medium / L3 — Effect of adverse opinion on ability to report on supplementary information
(1, 'Other Information and Supplementary Information', 'Whitfield & Crane CPA issues an adverse opinion on Lakewood Manufacturing''s financial statements due to pervasive misstatements in inventory valuation. The auditor was also engaged to report on a schedule of production costs in relation to the financial statements. What is the most likely effect of the adverse opinion on the supplementary information report?', '["The auditor may still issue an unmodified in-relation-to opinion if the schedule is correctly derived from accounting records", "The auditor should evaluate whether the adverse opinion''s basis also affects the supplementary information and consider modifying or withholding the in-relation-to opinion accordingly", "The auditor must issue an adverse opinion on the supplementary information as well", "The auditor should issue the in-relation-to opinion with no reference to the adverse financial statement opinion"]'::jsonb, 1, 'Correct (B): AU-C 725.A14-.A15 indicates that when the financial statement opinion is modified, the auditor should evaluate whether the circumstances also affect the supplementary information. Unlike a disclaimer where no opinion base exists, an adverse opinion may or may not affect the supplementary schedules depending on the nature of the misstatements. Wrong (A): Issuing an unmodified in-relation-to opinion without considering the adverse opinion''s impact would be inappropriate. Wrong (C): The auditor does not automatically issue a matching adverse opinion on the supplementary information. Wrong (D): Ignoring the adverse opinion when reporting on supplementary information would be misleading.', 'medium', 3),

-- Q8: medium / L2 — Agreeing supplementary information to underlying records
(1, 'Other Information and Supplementary Information', 'Pemberton & Associates CPA is engaged to report on a schedule of loan balances in relation to Heritage Credit Union''s audited financial statements. During procedures, the auditor traces each loan balance on the schedule to the general ledger and subsidiary records. This procedure is performed to satisfy which AU-C 725 requirement?', '["Verifying that management has signed a representation letter about the schedule", "Confirming that the supplementary information agrees to or can be reconciled with the underlying accounting records", "Establishing that the schedule qualifies as required supplementary information", "Determining that the supplementary information is presented in a format required by the standard-setter"]'::jsonb, 1, 'Correct (B): AU-C 725.08 requires the auditor to determine whether the supplementary information agrees to, or can be reconciled with, the underlying accounting and other records used to prepare the financial statements. Tracing balances to the general ledger directly addresses this requirement. Wrong (A): While management representations may be obtained, the tracing procedure relates to agreement with records rather than representation letters. Wrong (C): Loan balance schedules are voluntary supplementary information, not RSI. Wrong (D): Although format matters, tracing to accounting records tests agreement with underlying data, not format compliance.', 'medium', 2),

-- Q9: medium / L2 — Timing of auditor obtaining other information
(1, 'Other Information and Supplementary Information', 'Crestline Biotech provides its auditor, Harper & Blake CPA, with the final version of the annual report six weeks after the audit report date. The annual report contains a chairman''s letter with financial highlights referencing audited figures. Under AU-C 720, what is the auditor''s obligation regarding this document?', '["The auditor has no obligation because the other information was received after the report date", "The auditor should read the chairman''s letter and evaluate it for material inconsistencies with the audited financial statements", "The auditor should reissue the audit report to include an opinion on the chairman''s letter", "The auditor should perform additional audit procedures on any new data in the chairman''s letter"]'::jsonb, 1, 'Correct (B): AU-C 720.16-.17 requires that when other information is obtained after the date of the auditor''s report, the auditor should read the other information and evaluate it for material inconsistencies. However, the auditor is not required to update audit procedures for post-report-date other information. Wrong (A): Although the timing is after the report date, AU-C 720 still requires the auditor to read and consider other information obtained subsequently. Wrong (C): Reissuing the audit report is not required for post-report-date other information unless a material inconsistency or misstatement requires action. Wrong (D): Additional audit procedures are not required for other information received after the report date.', 'medium', 2),

-- Q10: easy / L1 — RSI versus supplementary information terminology
(1, 'Other Information and Supplementary Information', 'What distinguishes required supplementary information (RSI) from other types of supplementary information that accompany audited financial statements?', '["RSI is always prepared by the auditor, while other supplementary information is prepared by management", "RSI is mandated by a designated accounting standard-setter, while other supplementary information is voluntarily presented", "RSI requires a full-scope audit, while other supplementary information requires only limited procedures", "RSI is included within the basic financial statements, while other supplementary information is presented separately"]'::jsonb, 1, 'Correct (B): AU-C 730.02 defines RSI as information that a designated accounting standard-setter (such as GASB or FASB) requires to accompany the basic financial statements. In contrast, voluntary supplementary information under AU-C 725 is presented at management''s discretion and is not mandated by a standard-setter. Wrong (A): Both RSI and other supplementary information are prepared by management, not the auditor. Wrong (C): RSI requires only limited procedures, not a full-scope audit, whereas voluntary supplementary information may receive an in-relation-to opinion. Wrong (D): RSI accompanies but is outside the basic financial statements, not included within them.', 'easy', 1),

-- Q11: hard / L4 — Evaluating RSI that contradicts audited financial statement disclosures
(1, 'Other Information and Supplementary Information', 'Blackwell County''s comprehensive annual financial report includes RSI pension schedules showing a net pension liability of $14.2 million, but the audited government-wide financial statements report the net pension liability as $11.8 million. The auditor, Townsend & Archer CPA, determines that the RSI was prepared using updated actuarial assumptions received after the financial statement measurement date. Evaluate the most appropriate auditor response.', '["Report a material departure from prescribed guidelines in the RSI section of the auditor''s report because the RSI uses different assumptions than the financial statements", "Require management to revise the financial statements to reflect the updated actuarial assumptions from the RSI", "Inquire whether the RSI measurement date and methods comply with the applicable framework guidelines and report any departures identified", "Issue a qualified opinion on the basic financial statements due to the inconsistency between the RSI and the financial statement amounts"]'::jsonb, 2, 'Correct (C): AU-C 730.07-.09 requires the auditor to inquire about whether RSI is prepared in accordance with prescribed guidelines, including appropriate measurement dates. Rather than automatically reporting a departure, the auditor should first determine whether the RSI methods comply with the applicable framework before deciding on reporting action. Wrong (A): Although reporting departures is required when they exist, the auditor must first investigate whether the different assumptions constitute a departure from prescribed guidelines. Wrong (B): The financial statements reflect the proper measurement date; updating them for post-measurement-date assumptions would be inappropriate. Wrong (D): Differences between RSI and financial statements do not affect the opinion on the basic financial statements.', 'hard', 4),

-- Q12: easy / L1 — Purpose of other-matter paragraph for supplementary information
(1, 'Other Information and Supplementary Information', 'When an auditor includes an other-matter paragraph about supplementary information in the auditor''s report, what is the primary purpose of this paragraph?', '["To express an adverse opinion on the supplementary information", "To communicate information about the supplementary information that is relevant to users'' understanding", "To require management to revise the supplementary information before publication", "To transfer responsibility for the supplementary information from management to the auditor"]'::jsonb, 1, 'Correct (B): AU-C 706.08 and AU-C 725.09 indicate that an other-matter paragraph communicates information not presented in the financial statements that is relevant to users'' understanding of the audit, the auditor''s responsibilities, or the report. For supplementary information, it typically clarifies the scope of the auditor''s work. Wrong (A): Unlike an adverse opinion, an other-matter paragraph provides additional context about matters relevant to the report. Wrong (C): The auditor cannot require management to revise supplementary information through a report paragraph. Wrong (D): Responsibility for supplementary information remains with management regardless of any paragraph in the auditor''s report.', 'easy', 1),

-- Q13: medium / L2 — Auditor responsibility for other information in a document not containing FS
(1, 'Other Information and Supplementary Information', 'Cascade Ventures LLC publishes a separate investor newsletter that references several figures from the company''s audited financial statements but does not include the financial statements themselves. The auditor, Donovan & Cruz CPA, receives a copy of the newsletter. Under AU-C 720, what is the auditor''s responsibility?', '["Read the newsletter and evaluate whether the referenced financial data is materially consistent with the audited financial statements", "Ignore the newsletter because it does not contain the audited financial statements", "Audit the newsletter and issue a separate report on its accuracy", "Request that management cease referencing audited figures in external publications"]'::jsonb, 0, 'Correct (A): AU-C 720.05 extends the auditor''s responsibility to documents that reference audited financial statement information, even when those documents do not contain the financial statements. Although the newsletter is a separate publication, its references to audited data bring it within scope. Wrong (B): While the newsletter does not contain the financial statements, AU-C 720 requires reading documents that reference audited information when the auditor obtains them. Wrong (C): The auditor reads and considers the newsletter but does not audit it or issue a separate report. Wrong (D): The auditor has no authority to direct management''s external communications.', 'medium', 2),

-- Q14: hard / L3 — Analyzing effect of RSI departures on users
(1, 'Other Information and Supplementary Information', 'Pinewood Township presents its ten-year infrastructure condition data as RSI. The auditor identifies that the township used a modified approach for reporting infrastructure condition but omitted the required disclosure of estimated costs to maintain assets at the target condition level. Under AU-C 730, what is the most likely effect of this omission on the auditor''s report?', '["The auditor should issue a qualified opinion on the basic financial statements for the incomplete RSI disclosure", "The auditor should describe the specific omitted disclosure as a departure from prescribed guidelines in the RSI section of the report", "The auditor should perform additional audit procedures to estimate the maintenance costs independently", "The auditor should treat the omission as immaterial because infrastructure condition data is supplementary"]'::jsonb, 1, 'Correct (B): AU-C 730.10 requires the auditor to report material departures from prescribed guidelines in the RSI section of the auditor''s report. Omitting a required disclosure element constitutes a departure that should be specifically described so users understand the limitation. Wrong (A): Although the omission is significant for RSI users, departures in RSI do not affect the opinion on the basic financial statements. Wrong (C): The auditor performs limited procedures on RSI rather than independent estimation of missing data. Wrong (D): Required disclosures under GASB guidelines for the modified approach are substantive elements that cannot be dismissed as immaterial without evaluation.', 'hard', 3),

-- Q15: medium / L3 — Interaction between going concern and other information
(1, 'Other Information and Supplementary Information', 'Sentinel Aerospace Corp.''s annual report contains a management narrative asserting strong future growth prospects and expanding market share. However, the auditor has added a going concern emphasis-of-matter paragraph to the audit report. The auditor is evaluating the other information under AU-C 720. What is the most likely analytical concern?', '["The going concern paragraph automatically invalidates all forward-looking statements in the other information", "The management narrative may contain a material inconsistency with the audited financial statements if it contradicts the going concern conditions disclosed in the notes", "The auditor must require management to remove all positive projections from the annual report", "The going concern paragraph has no relevance to the auditor''s reading of the other information"]'::jsonb, 1, 'Correct (B): AU-C 720.12-.14 requires the auditor to consider whether other information is materially inconsistent with the financial statements. When going concern conditions are disclosed, a management narrative asserting strong growth without acknowledging uncertainty may constitute a material inconsistency. However, this requires judgment about whether the narrative contradicts the disclosed conditions. Wrong (A): A going concern paragraph does not automatically invalidate forward-looking statements; the auditor evaluates consistency rather than applying a blanket prohibition. Wrong (C): The auditor cannot require management to remove content from the annual report. Wrong (D): Going concern conditions are directly relevant to evaluating whether the other information is consistent with the financial statements.', 'medium', 3),

-- Q16: easy / L1 — Reporting framework for supplementary information
(1, 'Other Information and Supplementary Information', 'Under AU-C 725, which professional standard governs the auditor''s reporting on supplementary information presented in relation to the financial statements as a whole?', '["AU-C 700 on forming an opinion on financial statements", "AU-C 725 on supplementary information in relation to the financial statements", "AT-C 105 on attestation examination engagements", "AR-C 80 on compilation of financial statements"]'::jsonb, 1, 'Correct (B): AU-C 725 specifically governs the auditor''s responsibilities when engaged to report on supplementary information in relation to the financial statements as a whole. It establishes the conditions, procedures, and reporting requirements for such engagements. Wrong (A): While AU-C 700 governs the financial statement opinion, it does not address supplementary information reporting. Wrong (C): AT-C 105 governs attestation engagements, which differ from in-relation-to reporting under AU-C 725. Wrong (D): AR-C 80 addresses compilation engagements, which are fundamentally different from audit-based supplementary information reporting.', 'easy', 1),

-- Q17: medium / L3 — Evaluating whether other information misstatement of fact requires action
(1, 'Other Information and Supplementary Information', 'While reading Ironworks Manufacturing''s annual report, the auditor at Bancroft & Lee CPA identifies that the report states the company has 14 manufacturing facilities, but public filings and audit evidence indicate only 9 active facilities. The company had 5 facilities that were permanently closed during the year. How should the auditor analyze this matter under AU-C 720?', '["Ignore the discrepancy because facility counts are not financial statement data and fall outside the auditor''s responsibility", "Evaluate whether the statement represents a material misstatement of fact and discuss the matter with management to seek correction", "Issue a qualified opinion on the financial statements because the facility count affects asset valuations", "Require management to engage a separate auditor to verify the facility count independently"]'::jsonb, 1, 'Correct (B): AU-C 720.15-.16 requires the auditor to respond when a material misstatement of fact is identified in other information. Although facility counts are not financial statement amounts, overstating the number of active facilities could mislead users. The auditor should discuss the matter with management and seek correction. Wrong (A): While facility counts are not financial data, AU-C 720 extends the auditor''s responsibility to material misstatements of fact in other information, not only to inconsistencies with financial statement amounts. Wrong (C): A facility count error in other information does not warrant a modified opinion on the financial statements. Wrong (D): The auditor addresses misstatements of fact by discussing with management rather than requiring a separate engagement.', 'medium', 3),

-- Q18: medium / L3 — RSI presented with financial statements of a component in a group audit
(1, 'Other Information and Supplementary Information', 'Bridgeport Consolidated School District includes RSI schedules for both the primary government and its component unit, the school building authority. The component unit''s RSI was prepared by separate management using different actuarial assumptions for pension data. The group auditor is evaluating the combined RSI presentation. What is the most likely analytical implication?', '["The group auditor should accept the component unit''s RSI without further inquiry because it was prepared by separate management", "The group auditor should evaluate whether the component unit''s RSI was prepared in accordance with the same prescribed guidelines and note any departures in the RSI section", "The group auditor should exclude the component unit''s RSI from the report because it was not prepared by the primary government", "The group auditor should issue a separate audit report on the component unit''s RSI"]'::jsonb, 1, 'Correct (B): AU-C 730.07-.08 requires the auditor to evaluate whether RSI has been prepared in accordance with prescribed guidelines, regardless of which management prepared it. In a group audit, the group auditor should assess whether the component unit''s RSI follows the same framework requirements and report any identified departures. Wrong (A): Although separate management prepared it, the group auditor cannot accept RSI without inquiry; limited procedures are still required. Wrong (C): RSI for component units that is required by the framework should be included rather than excluded from the reporting. Wrong (D): RSI is subject to limited procedures, not a separate audit; the group auditor reports on RSI within the main auditor''s report.', 'medium', 3)
;

COMMIT;
